const temPrefixo = /^\s*ALERTA\b/i.test(text);
let slug = '', msg = text;
if (temPrefixo) {
  const m = text.match(/^\s*ALERTA\s*[·:|\-]\s*([a-z0-9_-]+)\s*[·:|\-]\s*(.+)$/i);
