  registra(sd, agora, `descartado no silêncio ${tipo} ${quem}`);
  return [{ json: { decisao: 'descartado: silêncio 21h–7h' } }];
}
if (leadId || nome) sd.dedupe[dk] = agora;

// ---- enfileira ----
if (tipo === 'sem_resposta') {
  const desde = agora - esperaEmMs(msg);
