    sd.saida.push({ id: `t${agora}`, jid, tipo, teste: true, digest: true, nome: unidadeNome, itens: [{ nome: quem, desde, link }], quando: agora + rand(JITTER_MIN_S, JITTER_MAX_S) * 1000, expira: agora + 30 * MIN });
