  registra(sd, agora, `fila ${tipo} ${quem} (${unidadeNome})${teste ? ' [TESTE]' : ''}`);
  return [{ json: { decisao: teste ? 'teste: sai em ~1-2 min para o João' : 'guardado para o resumo de 15 min' } }];
}
let corpo;
if (tipo === 'bandeira') {
  corpo = `🚩 *Bandeira vermelha · ${unidadeNome}*\n👤 ${quem} — sinal de alerta. Ligar agora.${link ? `\n🔗 ${link}` : ''}`;
} else {
  const det = ((msg.replace(/\s*Confirmar com o paciente\.?/i, '').match(/agendad[ao] pela i\.?\s*a(?:\s*sofia)?\s*[—:\-]\s*(.+)$/i) || [])[1] || '').replace(/[.\s]+$/, '');
  corpo = `🤖 *Consulta agendada pela I.A · ${unidadeNome}*\n👤 ${quem}${det ? ` — ${det.slice(0, 80)}` : ''}${link ? `\n🔗 ${link}` : ''}`;
}
let quando = agora + rand(JITTER_MIN_S, JITTER_MAX_S) * 1000;
if (silencio) quando = proximoFimDoSilencio(agora, CFG) + rand(JITTER_MIN_S, JITTER_MAX_S) * 1000;
const mencao = tipo === 'bandeira' && u && u.mention && !teste ? u.mention : '';
if (mencao) corpo += `\n\n@${mencao}`;
sd.saida.push({ id: `${tipo[0]}${agora}`, dk, jid, tipo, teste, quando, expira: quando + (tipo === 'bandeira' ? 14 * HORA : 3 * HORA), text: corpo, mention: mencao });
conta(sd, agora, `entrou:${tipo}`);
registra(sd, agora, `saida ${tipo} ${quem} (${unidadeNome})${teste ? ' [TESTE]' : ''} p/ ${new Date(quando).toISOString()}`);
return [{ json: { decisao: silencio ? 'bandeira guardada até 7h' : `${tipo}: sai em ~${Math.round((quando - agora) / 1000)} s (próximo minuto do relógio)` } }];

// ===== CONFIG (edite aqui) =====
const INSTANCIA = 'alertas3';              // << ÚNICO lugar da instância da Evolution. Trocar o remetente = trocar esta linha.
const TETO_POR_HORA = 6;                   // mensagens por hora, por grupo
const SILENCIO_INICIO = 21, SILENCIO_FIM = 7; // hora de Brasília
const INTERVALO_MIN_S = 20;                // folga mínima entre dois envios quaisquer deste remetente
const DIGEST_MIN = 15;                     // resumo de "sem resposta" a cada 15 min (relógio: :00 :15 :30 :45)
const JITTER_MIN_S = 20, JITTER_MAX_S = 90;
const MAX_LINHAS = 8;                      // pacientes listados por resumo
const FILA_MAX_HORAS = 6;                  // paciente na fila há mais que isto sai da lista (não vira alerta velho)
const URL_ENVIO = '__URL_ENVIO__';          // webhook interno deste mesmo workflow (o importar.sh preenche; contém o segredo)
const CFG = { SILENCIO_INICIO, SILENCIO_FIM };
// ===== AUXILIARES (iguais nos dois nós; o build cola este bloco nos dois) =====
const MIN = 60 * 1000;
const HORA = 60 * MIN;
const BRT = -3 * HORA; // America/Sao_Paulo = UTC-3 (sem horário de verão desde 2019)
const rand = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
// Relógio de parede de Brasília: campos UTC de uma data deslocada em -3h.
const brt = (ts) => {
  const d = new Date(ts + BRT);
  const p2 = (n) => String(n).padStart(2, '0');
  return { hora: d.getUTCHours(), dia: `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}` };
};
const emSilencio = (ts, c) => { const h = brt(ts).hora; return h >= c.SILENCIO_INICIO || h < c.SILENCIO_FIM; };
// Próximo SILENCIO_FIM:00 (hora de Brasília) a partir de ts.
const proximoFimDoSilencio = (ts, c) => {
  const l = new Date(ts + BRT);
  let alvo = Date.UTC(l.getUTCFullYear(), l.getUTCMonth(), l.getUTCDate(), c.SILENCIO_FIM, 0, 0);
  if (alvo <= ts + BRT) alvo += 24 * HORA;
  return alvo - BRT;
};
// Só atribui o que falta: o n8n marca o static data como "mudou" a cada atribuição, e queremos gravar só quando há mudança de verdade.
const iniciaSd = (sd) => {
  const pad = { fila: {}, saida: [], dedupe: {}, envios: {}, ultimoSlot: {}, contagem: {}, log: [], ultimoEnvio: 0, tetoLog: 0 };
  for (const k in pad) if (sd[k] === undefined) sd[k] = pad[k];
  return sd;
};
const conta = (sd, ts, chave) => {
  const d = brt(ts).dia;
  sd.contagem[d] = sd.contagem[d] || {};
  sd.contagem[d][chave] = (sd.contagem[d][chave] || 0) + 1;
};
const registra = (sd, ts, linha) => {
  const p = brt(ts);
  sd.log.push(`${p.dia} ${String(p.hora).padStart(2, '0')}:${String(new Date(ts).getUTCMinutes()).padStart(2, '0')} ${linha}`);
  if (sd.log.length > 120) sd.log.splice(0, sd.log.length - 120);
};
// "há 25 min" / "há 1h05" / "há 2h" / "há 3 horas" -> ms (0 se não achar).
